# Source for q/ae-instr-contrast2.js: Echo instrumentation (optimization, TEE/interventional findings), Contrast.
EI="Echo instrumentation"; CO="Contrast"
Q=[
# --- Color Doppler settings for regurgitation ---
(EI,"For grading valve regurgitation with color Doppler, the Nyquist limit is usually set at about:","50 to 70 cm/s",["10 to 20 cm/s","150 to 200 cm/s","Whatever the default is"],"Lower scales make jets look larger; standard settings make studies comparable.","F"),
(EI,"Lowering the color scale (Nyquist limit) makes a regurgitant jet look:","Larger",["Smaller","The same","Absent"],"Slower flow at the jet edges is now colored. This is why scale must be standardized.","F"),
(EI,"Raising color gain until speckles appear and then reducing it slightly:","Gives the best sensitivity without blooming",["Always overestimates jets","Turns off color","Causes aliasing"],"Too much gain inflates jet area; too little hides small jets.","F"),
(EI,"A narrow color sector over the valve of interest helps by:","Raising the color frame rate so brief jets are seen",["Lowering resolution","Increasing aliasing","Reducing sensitivity"],"Short jets, such as early systolic MR, can be missed at low frame rates.","F"),
(EI,"Color jet area alone is a poor measure of regurgitation severity because it depends on:","Machine settings, jet direction and loading conditions",["Only the true regurgitant volume","Heart rate only","Nothing; it is very accurate"],"Integrate vena contracta, PISA, CW density and flow reversals.","F"),
# --- Spectral settings ---
(EI,"For CW Doppler of a high-velocity jet (such as AS or MR), the wall filter is usually:","Set higher to remove low-velocity noise near the baseline",["Turned completely off","Set to zero always","Irrelevant"],"For tissue Doppler, the wall filter is set low or off.","F"),
(EI,"Pulsed-wave Doppler is preferred over CW for:","Measuring velocity at a specific location, such as mitral inflow or LVOT",["Measuring a 5 m/s AS jet","Measuring TR peak velocity","Any high velocity"],"CW measures the highest velocity along the beam but can't say where it came from.","F"),
(EI,"Doppler signals in echo are usually recorded with the sweep speed at:","50 to 100 mm/s",["5 mm/s","500 mm/s","Sweep speed doesn't matter"],"Faster sweeps improve timing accuracy; slower sweeps show respiratory variation.","F"),
(EI,"For pericardial constriction or tamponade, respiratory variation is best shown by:","A slow sweep speed with a respirometer trace",["Fast sweep speed","M-mode only","No respiratory trace"],"Mark inspiration and expiration to compare E velocities.","F"),
(EI,"For tissue Doppler e′, the sample volume should be about:","5 to 10 mm, placed at the septal and lateral mitral annulus",["30 mm in the LV cavity","1 mm in the LA","At the apex"],"Align the beam with annular motion and avoid angles over 20°.","F"),
(EI,"Harmonic imaging is generally NOT used for spectral Doppler because:","Doppler uses the fundamental frequency, and harmonics do not improve velocity measurement",["Harmonics increase aliasing","Harmonics remove the signal","Harmonics are only for color"],"Harmonics are used for 2D (and contrast) imaging.","C"),
(EI,"When recording cine loops in sinus rhythm, the usual standard is:","At least 3 beats per loop",["Only 1 beat","10 beats every time","No ECG needed"],"Record more beats (5 or more) in atrial fibrillation or irregular rhythm.","F"),
(EI,"A poor ECG signal on the echo machine affects:","Timing of measurements and triggered loop acquisition",["Doppler velocity accuracy directly","Transducer frequency","Image depth"],"Reposition leads and check the gain on the ECG trace.","F"),
# --- 2D optimization in echo ---
(EI,"To image the LV apex clearly, the sonographer should:","Reduce depth, move the focus to the apex and use a higher frequency or zoom",["Increase depth to maximum","Move the focus to the far field","Lower the frequency to minimum"],"Near-field clutter is reduced with harmonics and careful gain.","F"),
(EI,"Lung interference blocks parts of the image. The sonographer can improve this by:","Asking the patient to exhale and hold, or moving one rib space lower or more medial",["Increasing gain","Increasing depth","Using power Doppler"],"Lung tissue moves out of the way at end-expiration.","F"),
(EI,"Bright echoes in the LA that move with the aortic root and lie at the same depth on the opposite side are likely:","Side-lobe artifacts from the calcified aortic root",["LA thrombus","Myxoma","Cor triatriatum"],"Confirm in other views; real masses appear in multiple planes.","C"),
(EI,"For 3D full-volume acquisition, the patient should:","Hold their breath, with a regular rhythm, to avoid stitching artifacts",["Breathe rapidly","Talk during acquisition","Move position"],"Single-beat 3D avoids stitching but has lower volume rates.","F"),
(EI,"Echo-guided measurements of valve thickness should be done with:","Fundamental imaging or careful interpretation when harmonics are on",["Maximum gain","Color Doppler","Power Doppler"],"Harmonics make leaflets look thicker.","C"),
# --- TEE and intraoperative / interventional ---
(EI,"After mitral valve repair on intraoperative TEE, the team checks for:","Residual MR, mitral stenosis (gradient) and SAM with LVOT obstruction",["Coarctation","Bicuspid aortic valve","Pulmonary vein stenosis only"],"SAM after repair can often be managed with volume and stopping inotropes.","F"),
(EI,"After cardiopulmonary bypass, bright mobile echoes in the LV and aorta usually represent:","Retained air (microbubbles)",["Thrombus","Vegetations","Tumor"],"De-airing is done before coming off bypass; air can embolize to coronaries.","C"),
(EI,"During transcatheter edge-to-edge mitral repair (clip), TEE is used to:","Guide septal puncture, clip position and check residual MR and gradient",["Measure the aortic arch","Assess the pulmonic valve only","Replace fluoroscopy entirely"],"3D TEE shows the clip in relation to the leaflets.","F"),
(EI,"Transseptal puncture for left atrial procedures is guided by TEE to:","Puncture the fossa ovalis at a safe position",["Puncture the LV apex","Cross the aortic valve","Enter the coronary sinus"],"Tenting of the septum confirms the needle position before crossing.","F"),
(EI,"After left atrial appendage occlusion, TEE checks for:","Device position, compression, peri-device leak and device-related thrombus",["Aortic stenosis","Pulmonic regurgitation","Coarctation"],"Small residual leaks are common; larger leaks may need treatment.","C"),
(EI,"Before cardioversion, TEE is used mainly to:","Exclude left atrial appendage thrombus",["Measure EF","Assess the tricuspid valve","Measure the RV"],"Spontaneous echo contrast and low LAA velocities also indicate thrombus risk.","F"),
(EI,"During TAVR, echo helps to:","Measure the annulus, guide valve position and check for paravalvular leak and complications",["Close an ASD","Ablate the septum","Measure coronary calcium"],"Watch for new pericardial effusion and wall motion abnormalities.","F"),
(EI,"A new pericardial effusion during a catheter-based procedure suggests:","Cardiac perforation, a critical finding to report immediately",["Normal procedure","Device success","Mild MR"],"Monitor its size and look for tamponade physiology.","F"),
(EI,"A TEE finding that changes surgery immediately is:","Unexpected severe valve dysfunction or aortic dissection",["Trace TR","Normal EF","Mild LA enlargement"],"Intraoperative TEE regularly changes the surgical plan.","F"),
(EI,"Before TEE probe insertion, the probe tip should be checked for:","Correct flexion controls, locks unlocked and no damage",["Gel only","Battery level","Color settings"],"Never force the probe; locked tips can injure the esophagus.","F"),
(EI,"Advancing the TEE probe from the mid-esophagus into the stomach gives:","Transgastric views of the LV",["Upper esophageal aortic arch views","Suprasternal views","Parasternal views"],"Withdrawing the probe gives the upper esophageal views of the arch.","F"),
# --- Contrast: UEAs ---
(CO,"Commercial UEA microbubbles persist in the circulation because they contain:","Low-solubility, high-molecular-weight gases such as perflutren or sulfur hexafluoride",["Room air","Oxygen","Carbon dioxide only"],"Air bubbles dissolve quickly and don't survive the lungs.","F"),
(CO,"The shell of UEA microbubbles is made of:","Lipid, albumin or polymer",["Metal","Glass","Iodine"],"The shell stabilizes the bubble and affects how it responds to ultrasound.","F"),
(CO,"UEAs differ from CT and MRI contrast because they:","Stay in the blood vessels and are not toxic to the kidneys",["Contain iodine","Are excreted only by the kidneys and harm them","Are radioactive"],"The gas is breathed out through the lungs and the shell is metabolized.","F"),
(CO,"Contrast agents can be given as:","A slow bolus followed by a saline flush, or a continuous infusion",["An injection into muscle","An oral drink","A skin patch"],"Infusions give a steadier level, useful for perfusion and long studies.","F"),
(CO,"Using contrast during stress echo is helpful because:","It improves endocardial border detection, especially at peak heart rate",["It raises heart rate","It replaces the stress","It shows coronary anatomy"],"More confident wall motion reading reduces non-diagnostic studies.","F"),
(CO,"Myocardial contrast echocardiography assesses perfusion by:","Watching the rate at which bubbles refill the myocardium after high-MI destruction",["Measuring LV volume only","Measuring valve gradients","Using M-mode"],"Normal myocardium refills quickly; ischemic segments refill slowly.","C"),
(CO,"In normal myocardium at rest, contrast replenishment after a flash usually takes about:","4 to 5 seconds",["30 seconds","1 minute","It never refills"],"During stress, normal refill is faster, about 2 seconds.","C"),
(CO,"Contrast-specific imaging presets lower the mechanical index and:","Use pulse inversion or power modulation to show bubble signals over tissue",["Raise output power","Turn off harmonics","Raise the frequency to 10 MHz"],"The goal is strong bubble signals with little tissue signal and minimal bubble destruction.","F"),
(CO,"Contrast in an ICU patient on a ventilator is:","Generally safe and often helpful when images are poor",["Always forbidden","Only allowed with TEE","Toxic to the kidneys"],"Many critically ill patients have non-diagnostic images without contrast.","C"),
(CO,"Contrast helps detect LV free wall rupture or pseudoaneurysm by:","Showing contrast leaking outside the normal LV cavity",["Making the wall thicker","Showing turbulence only","Removing the effusion"],"It defines the true cavity borders.","C"),
(CO,"In LV noncompaction, contrast helps by:","Filling the deep trabecular recesses and outlining the compact layer",["Showing coronary flow","Removing trabeculations","Measuring gradients"],"This makes the noncompacted to compacted ratio easier to measure.","C"),
(CO,"Before giving a UEA, the sonographer should confirm:","The physician order, allergy history and a working IV",["Only the patient's weight","Nothing","That the patient has eaten"],"Have resuscitation equipment and trained staff available.","F"),
# --- Contrast: agitated saline technique ---
(CO,"A typical agitated saline mixture contains about:","8 mL saline, 0.5 to 1 mL air and sometimes a little of the patient's blood",["20 mL air only","Pure air","Contrast agent mixed with saline"],"Mix rapidly between two syringes through a three-way stopcock and inject immediately.","F"),
(CO,"Adding a small amount of the patient's blood to agitated saline:","Improves bubble stability and opacification",["Destroys the bubbles","Is required always","Makes the bubbles cross the lungs"],"Follow lab protocol.","C"),
(CO,"Large visible air bubbles should be removed before injecting saline because:","They could cause air embolism, especially with a right-to-left shunt",["They improve the study","They are needed for Valsalva","They show the PFO better"],"Only microbubbles are wanted.","F"),
(CO,"A femoral or leg vein injection may reveal a PFO missed by an arm injection because:","IVC flow is directed toward the atrial septum by the Eustachian valve",["Leg injections give more bubbles","The SVC drains into the LA","Arm veins don't reach the heart"],"SVC flow tends to stream toward the tricuspid valve instead.","C"),
(CO,"A PFO shunt is often graded by the number of bubbles in the LA. A large shunt is:","More than about 30 bubbles in one frame",["1 bubble","3 to 5 bubbles","Bubbles only after 10 beats"],"Small shunts show fewer than about 10 bubbles; moderate 10 to 30.","C"),
(CO,"A good Valsalva maneuver during a bubble study is confirmed by:","Leftward bowing of the interatrial septum on release",["Rightward bowing","No septal motion","A higher heart rate only"],"RA pressure must briefly exceed LA pressure to open the PFO.","F"),
(CO,"Bubbles that appear in the LA only after 3 to 5 or more beats, entering from the pulmonary veins, suggest:","An intrapulmonary shunt such as an arteriovenous malformation",["A PFO","An ASD","Normal finding"],"Hepatopulmonary syndrome and hereditary hemorrhagic telangiectasia are causes.","F"),
(CO,"Agitated saline from a left-arm injection that appears first in the LA suggests:","An unroofed coronary sinus with a persistent left SVC",["Normal anatomy","A PFO from the right","A VSD"],"The left SVC drains into an unroofed coronary sinus that opens into the LA.","C"),
(CO,"Agitated saline can confirm a pericardiocentesis needle position because:","Bubbles appear in the pericardial space, not in a heart chamber",["Saline dissolves the clot","It numbs the pericardium","It stops bleeding"],"If bubbles appear in the RV, the needle is in the heart.","F"),
(CO,"A negative bubble study (no bubbles in the left heart) with poor RA opacification is:","Non-diagnostic and should be repeated with better opacification",["Proof of no PFO","Proof of an ASD","Normal in all cases"],"The RA must be filled with bubbles at the septum for a valid result.","F"),
(CO,"In a patient with a known large ASD, agitated saline usually shows:","Some bubbles crossing to the LA and a negative contrast jet in the RA",["No bubbles anywhere","Bubbles only in the LV apex","Bubbles in the aorta only"],"Most flow is left-to-right, but a little right-to-left crossing is common.","C"),
(CO,"Saline contrast in the right heart can help identify:","RV borders, Ebstein anomaly and the right-sided chambers in complex anatomy",["LV wall motion","Mitral stenosis","Aortic stenosis"],"Bubbles outline the right heart because they don't normally cross the lungs.","C"),
]
